2	// 截获 Temu 后台商品接口的响应 JSON，通过 postMessage 传给 content.js（隔离世界）。
3	// 只读、不改请求；请求本身仍由页面自己发出（自带 cookie + anti-content 签名），故不触发风控。
4	(function () {
5	  if (window.__temuMonHooked) return;
6	  window.__temuMonHooked = true;
