// 下一次触发时间戳（本地时区）；若今天该时刻已过（或 5 秒内），排到明天
function nextWhen(hhmm) {
  const p = parseHHMM(hhmm);
  if (!p) return null;
  const now = new Date();
  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), p.h, p.min, 0, 0);
