// ---------------- 商品明细 → 带链接的告警行 ----------------
// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
function editLink(productId) {
  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
}
// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
function itemLines(items, total) {
  const lines = [];
  if (Array.isArray(items) && items.length) {
    for (const it of items) {
      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
    }
    if (typeof total === 'number' && total > items.length) {
      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
    }
  } else if (typeof total === 'number' && total > 0) {
    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
  }
  return lines;
}

// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
async function scanWatchViaTab() {
  const tab = await getGoodsTab();
  if (!tab) return null;
  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
}

// ---------------- 对比 & 告警（按店） ----------------
// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
const alertChains = {};
// v15：同一商品冷却期内不重复告警。切店/翻页会让「本页可见 decline 数」在 0↔1 抖动，
// 旧版按计数上升触发 → 一切店就再推一次。改成按 productId 去重。
const ALERT_COOLDOWN_MS = 6 * 60 * 60 * 1000; // 6 小时
function pruneAlertedMap(map, now) {
  const out = {};
  const keepFor = ALERT_COOLDOWN_MS * 4; // 保留 24h 历史，便于排障
  for (const id of Object.keys(map || {})) {
    const ts = map[id];
    if (typeof ts === 'number' && now - ts < keepFor) out[id] = ts;
  }
  return out;
}
// 从 items 里挑出冷却期外、尚未报过的新 productId
function pickFreshItems(items, alertedMap, now) {
  const fresh = [];
  const seen = {};
  for (const it of items || []) {
    if (!it || !it.productId) continue;
    const pid = String(it.productId);
    if (seen[pid]) continue;
    seen[pid] = true;
    const last = alertedMap && alertedMap[pid];
    if (typeof last === 'number' && now - last < ALERT_COOLDOWN_MS) continue;
    fresh.push(it);
  }
  return fresh;
}
function markAlerted(alertedMap, items, now) {
  const out = Object.assign({}, alertedMap || {});
  for (const it of items || []) {
    if (it && it.productId) out[String(it.productId)] = now;
  }
  return out;
}
function diffAndAlert(name) {
  const prev = alertChains[name] || Promise.resolve();
  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
  alertChains[name] = next;
  return next;
}

async function _diffAndAlert(name) {
  const cfg = await getConfig();
  if (!cfg.enabled) return;
  const stores = await getStores();
  const s = stores[name];
  if (!s) return;
  const latest = s.latest || {};
  const snap = s.snapshot || {};
  const events = [];
  const now = Date.now();
  let alertedWatch = pruneAlertedMap(snap.alertedWatchIds, now);
  let alertedDecline = pruneAlertedMap(snap.alertedDeclineIds, now);
  let newWatchItems = [];
  let newDeclineItems = [];

  // 在售数量下降 / 下架点名：v14 起关闭（DELIST_IN_PLUGIN=false），上下架由服务器赛狐负责。
  // 保留 countStatus 写入 latest.onSale 仅供 popup 展示与 waitForStoreCapture 就绪判断。
  if (DELIST_IN_PLUGIN && typeof latest.onSale === 'number' && typeof snap.onSale === 'number' && latest.onSale < snap.onSale) {
    events.push(`📉 在售数量下降：${snap.onSale} → ${latest.onSale}`);
  }

  // ---- 流量待关注（v15：只报在售 + 按 productId 去重）----
  // chip 计数含下架商品，不能单独当触发条件；必须扫到具体在售商品且是新 ID 才告警。
  // 首次 / 从 v14 升级：只把当前看到的商品记入 alerted，不发飞书。
  const hasWatchItems = Array.isArray(latest.watchItems) && latest.watchItems.length > 0;
  const watchCountUp = typeof snap.trafficWatch === 'number'
    && typeof latest.trafficWatch === 'number'
    && latest.trafficWatch > snap.trafficWatch;
  if (!snap.alertedWatchIds) {
    // 无 productId 基准（全新店，或 v14→v15）：seed 当前在售待关注，本轮不告警
    let seed = hasWatchItems
      ? latest.watchItems.filter((it) => it && it.saleStatus === 'onSale')
      : [];
    // 若 chip 已上升且本页没明细，主动扫一次只为 seed，仍不告警
    if (!seed.length && watchCountUp) {
      const scan = await scanWatchViaTab();
      if (scan && scan.applied && Array.isArray(scan.items)) {
        seed = scan.items.filter((it) => it && it.saleStatus !== 'removed');
      }
    }
    alertedWatch = markAlerted(alertedWatch, seed, now);
    log.info('Watch baseline seeded: store=' + name + ' known=' + Object.keys(alertedWatch).length);
  } else if (watchCountUp) {
    let items = Array.isArray(latest.watchItems) ? latest.watchItems.slice() : [];
    // chip 上升 → 主动点「在售中 + 待关注」捞全量在售明细
    const scan = await scanWatchViaTab();
    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
      items = scan.items; // scanWatchList 已标 saleStatus:'onSale'
    }
    // 主动扫的是在售 tab；被动的只要 onSale。统一排除 removed
    items = items.filter((it) => it && it.saleStatus !== 'removed');
    newWatchItems = pickFreshItems(items, alertedWatch, now);
    if (newWatchItems.length) {
      events.push(`⚠️ 商品流量待关注（在售新增 ${newWatchItems.length} 个）`);
      events.push(...itemLines(newWatchItems, newWatchItems.length));
      alertedWatch = markAlerted(alertedWatch, newWatchItems, now);
    } else {
      // chip 升了但没有新的在售商品（多半是下架把 chip 顶高，或都在冷却期）→ 静默
      log.info('Watch chip rose but no fresh on-sale items: store=' + name
        + ' chip=' + snap.trafficWatch + '→' + latest.trafficWatch
        + ' scanned=' + items.length);
      alertedWatch = markAlerted(alertedWatch, items, now);
    }
  } else if (hasWatchItems) {
    // chip 没升，但本页被动扫到了待关注商品 → 只报冷却期外的新 ID（不依赖 chip）
    const items = latest.watchItems.filter((it) => it && it.saleStatus === 'onSale');
    newWatchItems = pickFreshItems(items, alertedWatch, now);
    if (newWatchItems.length) {
      events.push(`⚠️ 商品流量待关注（在售新增 ${newWatchItems.length} 个）`);
      events.push(...itemLines(newWatchItems, newWatchItems.length));
      alertedWatch = markAlerted(alertedWatch, newWatchItems, now);
    }
  }

  // ---- 近期下降（v15：只报在售 + 按 productId 去重，不再用 0↔1 计数抖动触发）----
  // 旧版：snap.trafficDecline 会随本页可见数降回 0，再升回 1 就再报一次 → 切店刷屏。
  // 新版：无 alertedDeclineIds 时只 seed；之后只报冷却期外的新 productId。
  const rawDeclineItems = (Array.isArray(latest.declineItems) ? latest.declineItems : [])
    .filter((it) => it && it.saleStatus === 'onSale');
  if (!snap.alertedDeclineIds) {
    alertedDecline = markAlerted(alertedDecline, rawDeclineItems, now);
    log.info('Decline baseline seeded: store=' + name + ' known=' + Object.keys(alertedDecline).length);
  } else if (rawDeclineItems.length) {
    newDeclineItems = pickFreshItems(rawDeclineItems, alertedDecline, now);
    if (newDeclineItems.length) {
      events.push(`🔴 商品流量近期有下降（在售新增 ${newDeclineItems.length} 个，本页可见）`);
      events.push(...itemLines(newDeclineItems, null));
      alertedDecline = markAlerted(alertedDecline, newDeclineItems, now);
    }
  }

  if (events.length > 0) {
    log.info('Alert triggered: store=' + name
      + ' newWatch=' + newWatchItems.length
      + ' newDecline=' + newDeclineItems.length);
    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
  }

  // 合并式更新该店基准快照（只覆盖本次拿到的数值）。
  // 重新取一次 store：主动扫筛选期间 content 可能又上报过 latest，避免用旧闭包覆盖。
  const stores2 = await getStores();
  const s2 = stores2[name] || s;
  const L2 = s2.latest || latest;
  const newSnap = Object.assign({}, s2.snapshot || snap);
  if (typeof L2.onSale === 'number') newSnap.onSale = L2.onSale;
  if (typeof L2.total === 'number') newSnap.total = L2.total;
  if (typeof L2.trafficWatch === 'number') newSnap.trafficWatch = L2.trafficWatch;
  if (typeof L2.trafficDecline === 'number') newSnap.trafficDecline = L2.trafficDecline;
  newSnap.alertedWatchIds = alertedWatch;
  newSnap.alertedDeclineIds = alertedDecline;
  newSnap.ts = Date.now();
  s2.snapshot = newSnap;
  stores2[name] = s2;
  await saveStores(stores2);
  log.info('Snapshot updated: store=' + name
    + ' alertedWatch=' + Object.keys(alertedWatch).length
    + ' alertedDecline=' + Object.keys(alertedDecline).length);
}

// pageQuery 同商品 SKU 消失检测。
// 只对比「本轮 pageQuery 里再次出现的 productId」——当前页以外的商品本轮没看到，绝不判下架。
// 首轮只建 snapshot.productSkuMap，不告警。
async function diffProductSkus(name, products) {
  if (!Array.isArray(products) || !products.length) return 0;
  const cfg = await getConfig();
  const stores = await getStores();
  const s = stores[name] || { latest: {}, snapshot: {} };
  const prevMap = (s.snapshot && s.snapshot.productSkuMap) || {};
  const nextMap = Object.assign({}, prevMap);
  const removed = []; // { productId, productName, skc, skuId, name }
  let compared = 0;

  for (const p of products) {
    if (!p || !p.productId) continue;
    const pid = String(p.productId);
    const currSkus = Array.isArray(p.skus) ? p.skus : [];
    // 当前商品在本页出现但 SKU 列表空：可能接口字段漂移/截断，跳过该商品、保留旧基准
    if (!currSkus.length) continue;
    const currById = {};
    for (const sk of currSkus) {
      if (sk && sk.skuId) currById[String(sk.skuId)] = sk;
    }
    const prev = prevMap[pid];
    if (prev && prev.skus && typeof prev.skus === 'object') {
      compared += 1;
      for (const skuId of Object.keys(prev.skus)) {
        if (!currById[skuId]) {
          const old = prev.skus[skuId] || {};
          removed.push({
            productId: pid,
            productName: p.name || prev.name || '',
            skc: p.skc || prev.skc || '',
            skuId,
            name: old.name || skuId,
          });
        }
      }
    }
    // 更新该 product 的 SKU 基准（只记 id→name）
    const skusObj = {};
    for (const sk of currSkus) {
      if (sk && sk.skuId) skusObj[String(sk.skuId)] = { name: sk.name || '', img: sk.img || '' };
    }
    nextMap[pid] = {
      name: p.name || (prev && prev.name) || '',
      skc: p.skc || (prev && prev.skc) || '',
      skus: skusObj,
      ts: Date.now(),
    };
  }

  // 写回快照（合并式：本页商品更新，其它页旧基准保留）
  // 重新读 stores 避免覆盖并发写入
  const stores2 = await getStores();
  const s2 = stores2[name] || s;
  s2.snapshot = Object.assign({}, s2.snapshot || {}, { productSkuMap: nextMap });
  stores2[name] = s2;
  await saveStores(stores2);

  if (!removed.length) {
    if (compared) log.info('diffProductSkus: store=' + name + ' compared=' + compared + ' removed=0');
    return 0;
  }

  log.info('diffProductSkus: store=' + name + ' compared=' + compared + ' removed=' + removed.length);
  if (!cfg.enabled) return removed.length;

  const lines = [
    '**🏬 ' + name + '**',
    '📦 后台检测到 SKU 规格消失 **' + removed.length + '** 个（同商品内对比，非整 SKC 下架）',
    '',
  ];
  // 按商品分组展示
  const byProduct = {};
  for (const r of removed) {
    const k = r.productId;
    if (!byProduct[k]) byProduct[k] = { productId: k, productName: r.productName, skc: r.skc, skus: [] };
    byProduct[k].skus.push(r);
  }
  for (const g of Object.values(byProduct)) {
    const nm = String(g.productName || '商品').replace(/[[\]]/g, '').slice(0, 30);
    lines.push('• [' + nm + '](' + editLink(g.productId) + ')' + (g.skc ? '  SKC ' + g.skc : ''));
    for (const sk of g.skus) {
      lines.push('   ❌ ' + (sk.name || sk.skuId) + '  (skuId ' + sk.skuId + ')');
    }
  }
  lines.push('');
  lines.push('_说明：对比来源 = 商品列表 pageQuery 的 productSkuSummaries；仅对「本页再次出现的商品」做 SKU 集合 diff，避免分页误报。_');
  lines.push('_检查时间：' + new Date().toLocaleString('zh-CN') + '_');
  const fr = await sendFeishu(cfg.webhook, '🔔 Temu SKU 规格消失', lines, 'orange');
  await chrome.storage.local.set({
    lastAlert: { ts: Date.now(), ok: fr.ok, msg: fr.msg, store: name, kind: 'skuRemoved', lines },
  });
  return removed.length;
}

// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
