5	import { log } from './logger.js';
6	
7	// 注意：这些 helper 通过 page.evaluate 里的 eval(helpers) 注入。
8	// 必须用 function 声明（或 var），不能用 const/let：
9	// direct eval 的 const/let 只活在 eval 自己的词法环境里，外层 evaluate 回调访问不到
10	// （function 声明会进调用方变量环境，所以 findWatchChip 能用、realClick 却报 not defined）。
11	const DOM_HELPERS = `
12	  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
13	  function visible(el) {
14	    if (!el) return false;
15	    const r = el.getBoundingClientRect();
16	    return r.width > 0 && r.height > 0;
17	  }
18	  function textEls(re, maxLen = 40) {
19	    return [...document.querySelectorAll('*')].filter((e) => {
20	      const t = (e.textContent || '').trim();
