27	      if (p.tagName === 'BUTTON' || p.getAttribute('role') === 'button' || p.onclick) return p;
28	    }
29	    return el;
30	  }
31	  function realClick(el) {
32	    if (!el) return;
33	    const opts = { bubbles: true, cancelable: true, view: window };
34	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
35	      el.dispatchEvent(new MouseEvent(type, opts));
36	    }
37	  }
38	  async function waitFor(fn, timeout = 8000, step = 300) {
39	    const t0 = Date.now();
