45	    return null;
46	  }
47	  function readChipCount(label) {
48	    const re = new RegExp(label);
49	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
50	      if (!re.test(card.textContent || '')) continue;
