52	      if (cnt && /\\d/.test(cnt.textContent || '')) {
53	        return Number((cnt.textContent || '').replace(/[^\\d]/g, ''));
54	      }
55	      const m = (card.textContent || '').match(new RegExp(label + '[^\\\\d]{0,3}([\\\\d,]+)'));
56	      if (m) return Number(m[1].replace(/,/g, ''));
57	    }
58	    const all = [...document.querySelectorAll('*')];
59	    const labels = all
60	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
61	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
62	    for (const el of labels) {
63	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
64	        if (!cand) continue;
65	        const m = (cand.textContent || '').match(new RegExp(label + '[^\\\\d]{0,3}([\\\\d,]+)'));
66	        if (m) return Number(m[1].replace(/,/g, ''));
67	      }
68	    }
69	    return null;
70	  }
71	  function countDeclineBadges() {
72	    let n = 0;
73	    for (const e of document.querySelectorAll('*')) {
74	      const t = (e.textContent || '').trim();
75	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
76	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
77	      const r = e.getBoundingClientRect();
