92	          .filter((x) => x.length >= 6 && x.length <= 80 && /[\\u4e00-\\u9fff]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
93	          .sort((a, b) => b.length - a.length)[0] || '';
