111	    const el = [...document.querySelectorAll('*')].find(
112	      (x) => x.children.length === 0 && /共有\\s*[\\d,]+\\s*条/.test(x.textContent || '')
113	    );
114	    if (!el) return null;
115	    const m = (el.textContent || '').match(/共有\\s*([\\d,]+)\\s*条/);
116	    return m ? Number(m[1].replace(/,/g, '')) : null;
117	  }
118	  function findWatchChip() {
119	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
120	      if (/商品流量待关注/.test(card.textContent || '')) return card;
121	    }
122	    return null;
123	  }
124	  function clickReset() {
125	    const btn = textEls(/^重置$/, 6).filter(visible)[0];
126	    if (btn) realClick(clickableAncestor(btn));
