134	        const m = t.match(/(\\d[\\d,]*)/);
135	        if (m) return Number(m[1].replace(/,/g, ''));
136	      }
137	    }
138	    return null;
139	  }
140	`;
141	
142	/** 被动读：chip 待关注 + 下降徽标数 + 当前页明细 */
143	export async function readPassiveTraffic(page) {
144	  return page.evaluate((helpers) => {
145	    // eslint-disable-next-line no-eval
146	    eval(helpers);
147	    const products = scanProducts();
148	    const pick = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
149	    return {
150	      trafficWatch: readChipCount('商品流量待关注'),
151	      trafficDecline: countDeclineBadges(),
152	      watchItems: products.filter((p) => p.watch).map(pick),
153	      declineItems: products.filter((p) => p.decline).map(pick),
154	      gridReady: !!document.querySelector('[data-testid="beast-core-table-body-tr"]'),
155	    };
156	  }, DOM_HELPERS);
157	}
158	
159	/**
160	 * 主动点「商品流量待关注」筛选捞明细（对齐插件 scanWatchList）
161	 */
162	export async function scanWatchList(page) {
163	  const result = await page.evaluate(async (helpers) => {
164	    // eslint-disable-next-line no-eval
165	    eval(helpers);
166	    const chip = findWatchChip();
167	    if (!chip) return { items: [], applied: false, total: null, msg: '未找到待关注 chip' };
168	    const before = readTotalCount();
169	    realClick(clickableAncestor(chip));
170	    await waitFor(() => {
171	      const t = readTotalCount();
172	      return t != null && before != null && t !== before ? t : null;
173	    }, 8000, 300);
174	    await sleep(1200);
175	    const after = readTotalCount();
176	    const applied = after != null && before != null && after !== before && after <= before;
177	    let items = [];
178	    if (applied) {
179	      items = scanProducts().map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
180	    }
181	    if (applied) realClick(clickableAncestor(chip));
182	    clickReset();
183	    await waitFor(() => {
184	      const t = readTotalCount();
185	      return t != null && before != null && t >= before ? t : null;
186	    }, 6000, 300);
187	    await sleep(600);
188	    return { items, applied, total: after, before };
189	  }, DOM_HELPERS);
190	  log.info(
191	    `scanWatchList: applied=${result.applied} items=${(result.items || []).length} total=${result.total}`,
192	  );
193	  return result;
194	}
195	
196	/** 读在售 tab 数字 */
197	export async function readOnSaleTabCount(page) {
198	  return page.evaluate((helpers) => {
199	    // eslint-disable-next-line no-eval
200	    eval(helpers);
201	    return readTabCount('^在售中');
202	  }, DOM_HELPERS);
203	}
204	
205	export async function waitForGrid(page, timeout = 20000) {
206	  await page
207	    .locator('[data-testid="beast-core-table-body-tr"]')
208	    .first()
209	    .waitFor({ state: 'visible', timeout })
210	    .catch(() => {});
211	}
