    const backToAll = () => { const t = findTab(/^全部/); if (t) realClick(clickableAncestor(t)); };
    // ① 复位到干净、无快速筛选的状态：先回「全部」tab，再点「重置」清掉任何快速筛选 chip。
    backToAll();
    await sleep(300);
    clickReset();
    await sleep(1000);
    // ② 点「在售中」tab 并等视图生效（底部总数 == 在售 tab 计数）；点击可能被残留弹窗拦截 → 失败重试一次
    let tabCount = null;
    let viewOk = false;
    for (let attempt = 1; attempt <= 2 && !viewOk; attempt++) {
      const onSaleTab = findTab(/^在售中/);
      if (onSaleTab) realClick(clickableAncestor(onSaleTab));
      await waitFor(() => document.querySelector('[data-testid="beast-core-table-body-tr"]'), 8000, 300);
      await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
      tabCount = readTabCount(/^在售中/);
      if (tabCount == null) { viewOk = true; break; } // 读不到 tab 数 → 无法交叉验证，放行（后台仍有数量上限兜底）
      const ok = await waitFor(() => { const t = readTotalCount(); return (t != null && t === tabCount) ? true : null; }, 6000, 300);
      if (ok || readTotalCount() == null) { viewOk = true; break; } // 生效；footer 读不到 → 放行
      LOG.warn('scanOnSaleList: 在售视图未生效(第' + attempt + '次) gridTotal=' + readTotalCount() + ' tabCount=' + tabCount);
      clickReset();
      await sleep(800);
    }
    if (!viewOk) {
      LOG.warn('scanOnSaleList aborted: 在售视图两次都未生效，本轮放弃（不动基准）');
      backToAll();
      return { store: readStoreName(), items: [], onSaleTabCount: tabCount, msg: '在售视图未生效，本轮放弃扫描' };
    }
    // ③ 读干净视图下「在售中 N」的真实数字——作为 background 判定"是否扫全/是否被筛选污染"的权威值
    const onSaleTabCount = readTabCount(/^在售中/);
    const products = scanProducts();
    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
    // ④ 扫到的行数比「在售中 N」还多 = 视图污染（全部/未发布/别店商品混入）→ 放弃，绝不让它进基准
    if (onSaleTabCount != null && items.length > onSaleTabCount) {
      LOG.warn('scanOnSaleList aborted: scanned=' + items.length + ' > tabCount=' + onSaleTabCount + '（视图污染，本轮放弃）');
      backToAll();
      return { store: readStoreName(), items: [], onSaleTabCount: onSaleTabCount, msg: '扫描行数超过在售数，疑似视图污染，本轮放弃' };
    }
    var scanMsg = 'scanOnSale: tabCount=' + onSaleTabCount + ' scanned=' + items.length;
    if (items.length && onSaleTabCount && items.length < onSaleTabCount) scanMsg += ' (WARNING: possible page truncation)';
    LOG.info(scanMsg);
    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
    backToAll();
    LOG.info('scanOnSaleList done: items=' + items.length + ' onSaleTabCount=' + onSaleTabCount);
    return { store: readStoreName(), items: items, onSaleTabCount: onSaleTabCount };
  }

  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg || !msg.cmd) return;
    (async () => {
      try {
        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; } // 只读，不入锁
