  if(typeof obj!=='object') return;
  for(const k of Object.keys(obj)){
    const p=path?path+'.'+k:k;
    if(interesting.test(k)) hits.push({path:p, type: typeof obj[k], sample: Array.isArray(obj[k])?'[len '+obj[k].length+']': (obj[k]&&typeof obj[k]==='object'? '{..}' : String(obj[k]).slice(0,80))});
    walk(obj[k], p, hits, depth+1);
  }
}
const hits=[];
walk(items[0], 'item', hits);
console.log('interesting fields across first item:');
for(const h of hits) console.log(h.path, h.type, h.sample);

// Also aggregate unique values for channel-like / tag-like fields across all items
function collect(fieldPath){
  const vals=new Set();
  for(const it of items){
    let v=it;
    for(const part of fieldPath.split('.')){
      if(!v) break;
      if(part.endsWith('[0]')){ v=v[part.slice(0,-3)]; v=Array.isArray(v)?v[0]:null; }
      else v=v[part];
    }
    if(v!=null && typeof v!=='object') vals.add(String(v));
  }
  return [...vals].slice(0,20);
}
