1	import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
2	import { resolve } from 'node:path';
3	import { ROOT } from './config.js';
4	import { itemLines } from './alertFormat.js';
5	
6	const STATE_FILE = resolve(ROOT, 'data', 'state.json');
7	
8	export function loadState() {
9	  try {
10	    return JSON.parse(readFileSync(STATE_FILE, 'utf8'));
11	  } catch {
12	    return { stores: {} };
13	  }
14	}
15	
16	export function saveState(state) {
17	  mkdirSync(resolve(ROOT, 'data'), { recursive: true });
18	  writeFileSync(STATE_FILE, JSON.stringify(state, null, 2), 'utf8');
19	}
20	
21	/**
22	 * 对比本次扫描与快照，产出告警事件（含商品明细行）
23	 * @param {object} prev
24	 * @param {object} curr scanStore 结果
25	 * @param {object} alertsCfg
26	 * @param {{ editBaseUrl?: string, skipOnSaleDrop?: boolean }} [opts]
27	 *   skipOnSaleDrop：下架点名已由赛狐负责时，可跳过「仅数字」在售下降，避免双报
28	 */
29	export function diffStore(prev, curr, alertsCfg, opts = {}) {
30	  const events = [];
31	  const editBase = opts.editBaseUrl || 'https://agentseller.temu.com';
32	
33	  // 在售数量下降（数字）；完整下架点名优先走赛狐
34	  if (
35	    !opts.skipOnSaleDrop &&
36	    alertsCfg.onSaleDrop &&
37	    prev &&
38	    typeof prev.onSaleCount === 'number' &&
39	    typeof curr.onSaleCount === 'number' &&
40	    curr.onSaleCount < prev.onSaleCount
41	  ) {
42	    events.push({
43	      type: 'onSaleDrop',
44	      text: `在售商品数量下降：${prev.onSaleCount} → ${curr.onSaleCount}（减少 ${prev.onSaleCount - curr.onSaleCount} 件）`,
45	    });
46	  }
47	
48	  if (alertsCfg.trafficAnomaly !== false) {
49	    const prevWatch = prev?.trafficWatchCount;
50	    const currWatch = curr.trafficWatchCount;
51	    if (
52	      typeof prevWatch === 'number' &&
53	      typeof currWatch === 'number' &&
54	      currWatch > prevWatch
55	    ) {
56	      const lines = [
57	        `「商品流量待关注」增加：${prevWatch} → ${currWatch}（+${currWatch - prevWatch}）`,
58	        ...itemLines(curr.watchItems, currWatch, editBase),
59	      ];
60	      events.push({ type: 'trafficWatch', text: lines.join('\n') });
61	    }
62	
63	    // 近期下降：数字增加（插件 v 后）或 布尔从无到有
64	    const prevDec = prev?.trafficDeclineCount;
65	    const currDec = curr.trafficDeclineCount;
66	    if (
67	      typeof prevDec === 'number' &&
68	      typeof currDec === 'number' &&
69	      currDec > prevDec
70	    ) {
71	      const lines = [
72	        `「商品流量近期有下降」增加：${prevDec} → ${currDec}（本页可见徽标）`,
73	        ...itemLines(curr.declineItems, null, editBase),
74	      ];
75	      events.push({ type: 'trafficDecline', text: lines.join('\n') });
76	    } else if (
77	      prev &&
78	      curr.trafficDeclineExists &&
79	      !prev.trafficDeclineExists
80	    ) {
81	      // 必须有过基准：首轮 prev 为空只建快照，不报「从无到有」
82	      const lines = [
83	        '出现「商品流量近期有下降」商品，请及时处理。',
84	        ...itemLines(curr.declineItems, null, editBase),
85	      ];
86	      events.push({ type: 'trafficDecline', text: lines.join('\n') });
87	    }
88	  }
89	
90	  return events;
91	}
92	
93	/** 合并写入快照（null 轮 carry） */
94	export function mergeSnapshot(prev, result) {
95	  const carry = (cur, key) =>
96	    cur == null && prev && typeof prev[key] === 'number' ? prev[key] : cur;
97	  return {
98	    onSaleCount: carry(result.onSaleCount, 'onSaleCount'),
99	    trafficWatchCount: carry(result.trafficWatchCount, 'trafficWatchCount'),
100	    trafficDeclineCount: carry(result.trafficDeclineCount, 'trafficDeclineCount'),
101	    trafficDeclineExists: !!result.trafficDeclineExists,
102	    trafficAnomalyTotal:
103	      (carry(result.trafficWatchCount, 'trafficWatchCount') ?? 0) +
104	      (carry(result.trafficDeclineCount, 'trafficDeclineCount') ?? 0),
